   "text": "化簡 $\\dfrac{(2x^4)^3}{2x^5}$。\n\n$$(2x^4)^3 = 2^3 \\cdot x^{12} = 8x^{12}$$\n\n$$\\frac{8x^{12}}{2x^5} = 4x^{12-5} = 4x^7$$\n\n**答案：C　$4x^7$**",
   "html": "<p>化簡 $\\dfrac{(2x^4)^3}{2x^5}$。</p>\n<p>$$(2x^4)^3 = 2^3 \\cdot x^{12} = 8x^{12}$$</p>\n<p>$$\\frac{8x^{12}}{2x^5} = 4x^{12-5} = 4x^7$$</p>\n<p><strong>答案：C　$4x^7$</strong></p>",
