   "html": "<p>計算 $(4x+y)^2-(4x-y)^2$。</p>\n<p>用 $a^2-b^2=(a+b)(a-b)$，免展開：</p>\n<p>$$\\left[(4x+y)-(4x-y)\\right]\\left[(4x+y)+(4x-y)\\right] = (2y)(8x) = 16xy$$</p>\n<p><strong>答案：D　$16xy$</strong></p>",
