   "text": "第 1 個圖案有 1 點；第 $(n+1)$ 個圖案比第 $n$ 個多 $n$ 點。求第 8 個圖案的點數。\n\n逐個累加：$1,\\ 2,\\ 4,\\ 7,\\ 11,\\ 16,\\ 22,\\ 29$\n\n（通項：$\\dfrac{n(n-1)}{2}+1$；$n=8$ 時 $28+1=29$。）\n\n**答案：B　29**",
   "html": "<p>第 1 個圖案有 1 點；第 $(n+1)$ 個圖案比第 $n$ 個多 $n$ 點。求第 8 個圖案的點數。</p>\n<p>逐個累加：$1,\\ 2,\\ 4,\\ 7,\\ 11,\\ 16,\\ 22,\\ 29$</p>\n<p>（通項：$\\dfrac{n(n-1)}{2}+1$；$n=8$ 時 $28+1=29$。）</p>\n<p><strong>答案：B　29</strong></p>",
   "file": "2012_II_解答.md"
