   "text": "動點 $P$ 與定點 $(20,12)$ 的距離恆等於 $5$。\n\n與定點等距離的軌跡 = 圓。\n\n**答案：A　circle**",
   "html": "<p>動點 $P$ 與定點 $(20,12)$ 的距離恆等於 $5$。</p>\n<p>與定點等距離的軌跡 = 圓。</p>\n<p><strong>答案：A　circle</strong></p>",
