   "text": "設 $\\text{f}(x)=3x^3-7x^2+kx-8$，其中 $k$ 為一常數。已知 $\\text{f}(x)\\equiv(x-2)(ax^2+bx+c)$，其中 $a$、$b$ 及 $c$ 均為常數。\n\n(a) 求 $a$、$b$ 及 $c$。（4 分）\n\n(b) 某人宣稱方程 $\\text{f}(x)=0$ 所有的根均為實數。你是否同意？試解釋你的答案。（3 分）",
   "html": "<p>設 $\\text{f}(x)=3x^3-7x^2+kx-8$，其中 $k$ 為一常數。已知 $\\text{f}(x)\\equiv(x-2)(ax^2+bx+c)$，其中 $a$、$b$ 及 $c$ 均為常數。</p>\n<p>(a) 求 $a$、$b$ 及 $c$。（4 分）</p>\n<p>(b) 某人宣稱方程 $\\text{f}(x)=0$ 所有的根均為實數。你是否同意？試解釋你的答案。（3 分）</p>",
