   "text": "在某工場內，把 2 個底半徑均為 $R$ cm 的完全相同的實心金屬直立圓柱體熔化，並重鑄成 27 個底半徑均為 $r$ cm 及高均為 10 cm 的完全相同的較小的實心直立圓柱體。已知較大的圓柱體的底面積為較小的 9 倍。\n\n(a) 求\n\n　(i) $r:R$，\n\n　(ii) 較大的圓柱體的高。（5 分）\n\n(b) 某工匠宣稱較小的圓柱體與較大的圓柱體相似。你是否同意？試解釋你的答案。（2 分）",
   "html": "<p>在某工場內，把 2 個底半徑均為 $R$ cm 的完全相同的實心金屬直立圓柱體熔化，並重鑄成 27 個底半徑均為 $r$ cm 及高均為 10 cm 的完全相同的較小的實心直立圓柱體。已知較大的圓柱體的底面積為較小的 9 倍。</p>\n<p>(a) 求</p>\n<p>(i) $r:R$，</p>\n<p>(ii) 較大的圓柱體的高。（5 分）</p>\n<p>(b) 某工匠宣稱較小的圓柱體與較大的圓柱體相似。你是否同意？試解釋你的答案。（2 分）</p>",
