   "text": "(a) 圖 3(a) 顯示一張三角形紙卡 $ABC$，其中 $AB=28$ cm、$BC=21$ cm 及 $AC=35$ cm。設 $M$ 為 $AC$ 上的一點使得 $\\angle BMC=75°$。\n\n![2013 P1 Q18 圖 3(a)](2013P1_figs_svg/2013P1_Q18a.svg)\n\n求\n\n　(i) $\\angle BCM$，\n\n　(ii) $CM$。（3 分）\n\n(b) 文俊將 (a) 所描述的三角形紙卡沿 $BM$ 摺起，使得 $AB$ 及 $BC$ 均位於水平地面上，如圖 3(b) 所示。已知 $\\angle AMC=107°$。\n\n![2013 P1 Q18 圖 3(b)](2013P1_figs_svg/2013P1_Q18b.svg)\n\n　(i) 求在水平地面上 $A$ 與 $C$ 間的距離。\n\n　(ii) 設 $N$ 為 $BC$ 上的一點使得 $MN$ 垂直於 $BC$。文俊宣稱面 $BCM$ 與水平地面間的交角為 $\\angle ANM$。你是否同意？試解釋你的答案。（5 分）",
   "html": "<p>(a) 圖 3(a) 顯示一張三角形紙卡 $ABC$，其中 $AB=28$ cm、$BC=21$ cm 及 $AC=35$ cm。設 $M$ 為 $AC$ 上的一點使得 $\\angle BMC=75°$。</p>\n<p><img alt=\"2013 P1 Q18 圖 3(a)\" src=\"2013P1_figs_svg/2013P1_Q18a.svg\" /></p>\n<p>求</p>\n<p>(i) $\\angle BCM$，</p>\n<p>(ii) $CM$。（3 分）</p>\n<p>(b) 文俊將 (a) 所描述的三角形紙卡沿 $BM$ 摺起，使得 $AB$ 及 $BC$ 均位於水平地面上，如圖 3(b) 所示。已知 $\\angle AMC=107°$。</p>\n<p><img alt=\"2013 P1 Q18 圖 3(b)\" src=\"2013P1_figs_svg/2013P1_Q18b.svg\" /></p>\n<p>(i) 求在水平地面上 $A$ 與 $C$ 間的距離。</p>\n<p>(ii) 設 $N$ 為 $BC$ 上的一點使得 $MN$ 垂直於 $BC$。文俊宣稱面 $BCM$ 與水平地面間的交角為 $\\angle ANM$。你是否同意？試解釋你的答案。（5 分）</p>",
