   "text": "設 $k$ 為常數，解 $(x-k)^2=4k^2$。\n\n$$x-k=\\pm 2k \\;\\Rightarrow\\; x=3k \\text{ 或 } x=-k$$\n\n**答案：C　$x=-k$ 或 $x=3k$**",
   "html": "<p>設 $k$ 為常數，解 $(x-k)^2=4k^2$。</p>\n<p>$$x-k=\\pm 2k \\;\\Rightarrow\\; x=3k \\text{ 或 } x=-k$$</p>\n<p><strong>答案：C　$x=-k$ 或 $x=3k$</strong></p>",
