   "text": "> 圖中散點由左下向右上升，呈近似直線的正相關分布。\n\n**答案：A　當 $x$ 增加時，$y$ 增加**",
   "html": "<blockquote>\n<p>圖中散點由左下向右上升，呈近似直線的正相關分布。</p>\n</blockquote>\n<p><strong>答案：A　當 $x$ 增加時，$y$ 增加</strong></p>",
