   "text": "圓 $C$ 通過點 $A(6,11)$ 且 $C$ 的圓心為點 $G(0,3)$。\n\n(a)　求 $C$ 的方程。（2 分）\n\n(b)　$P$ 為直角坐標平面上的一動點使得 $AP=GP$。將 $P$ 的軌跡記為 $\\Gamma$。\n\n　　(i)　求 $\\Gamma$ 的方程。\n\n　　(ii)　描述 $\\Gamma$ 與線段 $AG$ 之間的幾何關係。\n\n　　(iii)　若 $\\Gamma$ 與 $C$ 相交於 $Q$ 及 $R$，求四邊形 $AQGR$ 的周界。（5 分）",
