   "text": "圖 6(a) 顯示以長方形為底的實心角錐體 $VABCD$，其中 $AB=18\\ \\mathrm{cm}$、$BC=10\\ \\mathrm{cm}$、$VB=VC=30\\ \\mathrm{cm}$ 及 $\\angle VAB=\\angle VDC=110^\\circ$。\n\n![2014 P1 Q17 圖6(a) 角錐體](2014P1_figs_svg/2014P1_Q17a.svg)\n\n(a)　求 $\\angle VBA$。（2 分）\n\n(b)　$P$、$Q$、$M$ 及 $N$ 分別為 $AB$、$CD$、$VB$ 及 $VC$ 的中點。從 $VABCD$ 切去 $PBCQNM$ 造成一幾何模型，如圖 6(b) 所示。某工匠宣稱梯形 $PQNM$ 的面積小於 $70\\ \\mathrm{cm}^2$。你是否同意？試解釋你的答案。（5 分）\n\n![2014 P1 Q17 圖6(b) 切去部分後模型](2014P1_figs_svg/2014P1_Q17b.svg)",
   "html": "<p>圖 6(a) 顯示以長方形為底的實心角錐體 $VABCD$，其中 $AB=18\\ \\mathrm{cm}$、$BC=10\\ \\mathrm{cm}$、$VB=VC=30\\ \\mathrm{cm}$ 及 $\\angle VAB=\\angle VDC=110^\\circ$。</p>\n<p><img alt=\"2014 P1 Q17 圖6(a) 角錐體\" src=\"2014P1_figs_svg/2014P1_Q17a.svg\" /></p>\n<p>(a)　求 $\\angle VBA$。（2 分）</p>\n<p>(b)　$P$、$Q$、$M$ 及 $N$ 分別為 $AB$、$CD$、$VB$ 及 $VC$ 的中點。從 $VABCD$ 切去 $PBCQNM$ 造成一幾何模型，如圖 6(b) 所示。某工匠宣稱梯形 $PQNM$ 的面積小於 $70\\ \\mathrm{cm}^2$。你是否同意？試解釋你的答案。（5 分）</p>\n<p><img alt=\"2014 P1 Q17 圖6(b) 切去部分後模型\" src=\"2014P1_figs_svg/2014P1_Q17b.svg\" /></p>",
