   "text": "(a)　圖 7 中，直線 $L_1$ 的方程為 $6x+7y=900$ 及直線 $L_2$ 的 $x$ 截距為 $180$。$L_1$ 與 $L_2$ 相交於點 $(45,90)$。陰影區域（包括邊界在內）表示某不等式組的解。求該不等式組。（4 分）\n\n![2014 P1 Q18 圖7 陰影區域](2014P1_figs_svg/2014P1_Q18.svg)\n\n(b)　某工廠生產 $X$ 及 $Y$ 兩款衣櫃。每個 $X$ 衣櫃需 $6$ 工時裝嵌及 $2$ 工時包裝，而每個 $Y$ 衣櫃需 $7$ 工時裝嵌及 $3$ 工時包裝。在某月，該工廠有 $900$ 工時可作裝嵌及 $360$ 工時可作包裝。生產一個 $X$ 衣櫃及一個 $Y$ 衣櫃的利潤分別為 $\\$440$ 及 $\\$665$。某工人宣稱該月的總利潤可超過 $\\$80\\,000$。你是否同意？試解釋你的答案。（4 分）",
   "html": "<p>(a)　圖 7 中，直線 $L_1$ 的方程為 $6x+7y=900$ 及直線 $L_2$ 的 $x$ 截距為 $180$。$L_1$ 與 $L_2$ 相交於點 $(45,90)$。陰影區域（包括邊界在內）表示某不等式組的解。求該不等式組。（4 分）</p>\n<p><img alt=\"2014 P1 Q18 圖7 陰影區域\" src=\"2014P1_figs_svg/2014P1_Q18.svg\" /></p>\n<p>(b)　某工廠生產 $X$ 及 $Y$ 兩款衣櫃。每個 $X$ 衣櫃需 $6$ 工時裝嵌及 $2$ 工時包裝，而每個 $Y$ 衣櫃需 $7$ 工時裝嵌及 $3$ 工時包裝。在某月，該工廠有 $900$ 工時可作裝嵌及 $360$ 工時可作包裝。生產一個 $X$ 衣櫃及一個 $Y$ 衣櫃的利潤分別為 $\\$440$ 及 $\\$665$。某工人宣稱該月的總利潤可超過 $\\$80\\,000$。你是否同意？試解釋你的答案。（4 分）</p>",
